class Solution {
public:
    int largest1BorderedSquare(vector<vector<int>>& grid) {
        int n = grid.size();
        int m = grid[0].size();
        vector<vector<int>> up(n, vector<int>(m, 0));
        vector<vector<int>> left(n, vector<int>(m, 0));

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 1) {
                    up[i][j] = (i == 0) ? 1 : up[i - 1][j] + 1;
                    left[i][j] = (j == 0) ? 1 : left[i][j - 1] + 1;
                }
            }
        }

        int best = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int maxK = min(i, j) + 1;
                for (int k = maxK; k >= 1; k--) {
                    if (k <= best) break;
                    if (left[i][j] >= k && up[i][j] >= k &&
                        left[i - k + 1][j] >= k && up[i][j - k + 1] >= k) {
                        best = k;
                        break;
                    }
                }
            }
        }

        return best * best;
    }
};
